parameters.functionCode:
const MAX_QUESTION = 600;

return items.map(item => {
  const payload = item.json || {};
  const endpointRaw = (payload.endpoint ?? '/inventaire').toString().trim();
  const sanitizedEndpoint = endpointRaw.startsWith('http')
    ? '/inventaire'
    : ('/' + endpointRaw.replace(/^\/+/, '')).replace(/[^a-zA-Z0-9/_-]/g, '').replace(/\/+/g, '/');

  const question = (payload.question ?? "Peux-tu analyser l'inventaire ?").toString().trim().slice(0, MAX_QUESTION);
  const user = (payload.user ?? 'anonyme').toString().trim().slice(0, 80);

  return {
    json: {
      endpoint: sanitizedEndpoint || '/inventaire',
      question,
      user,
      meta: {
        receivedAt: new Date().toISOString(),
        rawEndpoint: endpointRaw
      }
    }
  };
});

return items.map(item => {
  const apiStatus = item.json.statusCode ?? item.json.apiStatus ?? null;
  const apiPayload = item.json.body ?? item.json.apiResponse ?? item.json;
  const endpoint = item.json.endpoint ?? '/inventaire';
  const question = item.json.question ?? '';
  const preview = JSON.stringify(apiPayload ?? {}, null, 2);
  const limitedPreview = preview.length > 6000 ? `${preview.slice(0, 6000)}
…(tronqué)…` : preview;

  const prompt = [
    "Tu es un assistant expert en gestion d'inventaire.",
    "Consignes:",
    "- Réponds en français.",
    "- Sois factuel, concis (<=6 phrases) et oriente vers l'action.",
    "- Mets en avant ruptures, surstocks, anomalies et actions prioritaires.",
    "",
    `Contexte API (status ${apiStatus ?? '?' } sur ${endpoint}):`,
    limitedPreview,
    "",
    `Question utilisateur (${item.json.user ?? 'inconnu'}):`,
    question,
    "",
    "Forme ta réponse avec 2 sections courtes: 1/ Analyse 2/ Actions recommandées."
  ].join("
");

  return {
    json: {
      prompt,
      apiDataPreview: limitedPreview,
      apiStatus,
      endpoint,
      question,
      user: item.json.user ?? 'anonyme'
    }
  };
});

