return items.map(item => {
  const answer = item.json.message?.content ?? item.json.body?.message?.content ?? item.json.content ?? '';
  const model = item.json.model ?? 'llama3.1';

  return {
    json: {
      answer: answer || 'Réponse vide',
      endpoint: item.json.endpoint ?? '/inventaire',
      apiStatus: item.json.apiStatus ?? item.json.statusCode ?? null,
      model,
      promptUsed: item.json.prompt ?? undefined,
      generatedAt: new Date().toISOString()
    }
  };
});
